// A text with a gap ("Mauer 3 geschafft!") cannot have one recording for every value. It is said either as a
// whole sentence made beforehand for the common values (s/…), or put together from pieces: the fixed parts of
// the text and the value, each a file of its own (t/…). Both are generated by tools/voice-fills.ts and
// tools/voice-ai.py and listed in the manifest of the language.
import { voiceId } from '../voiceId.ts';

export interface Piece {
  text: string;
  /** the value of a gap (a name, a number, a letter) – may be missing as a file */
  gap: boolean;
}

/** file (below /voice/ai/<lang>/, without .mp3) of a whole sentence with its gaps filled */
export const sentenceFile = (text: string): string => `s/${voiceId(text)}`;

/** file of one piece as said by one speaker */
export const pieceFile = (voice: string, text: string): string => `t/${voice}-${voiceId(text)}`;

const LEAD = /^[\s:,;–\-)(]+/;
const TRAIL = /[\s)(,:;–\-]+$/;

/** the pieces of a template ("Mauer {n} geschafft!") filled with its values in the order of the gaps. A
 * name in front with a colon ("{name}: Schreibt …") is a heading and not said; "{n}×" stays together. */
export function piecesOf(template: string, values: string[]): Piece[] {
  const parts = template.split(/(\{\w+\})/);
  let skip = -1;
  if (/^\{\w+\}\s*:/.test(template)) {
    skip = 1;
    parts[2] = parts[2].replace(/^\s*:/, '');
  }
  const out: Piece[] = [];
  let v = 0;
  for (let i = 0; i < parts.length; i++) {
    const p = parts[i];
    if (/^\{\w+\}$/.test(p)) {
      const value = (values[v++] ?? '').trim();
      if (i === skip || !value) continue;
      let text = value;
      if (/^\s*×/.test(parts[i + 1] ?? '')) {
        text += '×';
        parts[i + 1] = parts[i + 1].replace(/^\s*×/, '');
      }
      out.push({ text, gap: true });
      continue;
    }
    const text = p.replace(LEAD, '').replace(TRAIL, '');
    if (/[\p{L}\p{N}]/u.test(text)) out.push({ text, gap: false });
  }
  return out;
}
